import assert from 'node:assert/strict';
import axios from 'axios';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.FIRECRAWL_API_KEY, 'the application receives its team API key');
const url = 'https://example.com/observatory';
const title = 'Observatory notes';
const html = '<!doctype html><html><head><title>Observatory notes</title></head><body><h1>Observatory notes</h1><p>Public telescope sessions begin at dusk.</p></body></html>';
const config = {
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.FIRECRAWL_API_KEY}` },
  timeout: 7500,
};
if (process.argv[2] !== 'readback') {
  const seeded = await axios.post('https://api.firecrawl.dev/_twin/pages', { url, title, html }, config);
  assert.equal(seeded.status, 201);
  assert.equal(seeded.data.url, url);
  assert.ok(seeded.data.id);
}
const { status, data: response } = await axios.post('https://api.firecrawl.dev/v2/scrape', {
  url, formats: ['markdown', 'rawHtml'], timeout: 7500,
}, config);
assert.equal(status, 200);
assert.equal(response.success, true);
assert.equal(response.data.rawHtml, html);
assert.equal(response.data.markdown, '# Observatory notes\n\nPublic telescope sessions begin at dusk.');
assert.equal(response.data.metadata.title, title);
assert.equal(response.data.metadata.sourceURL, url);
assert.equal(response.data.metadata.statusCode, 200);
assert.equal(response.data.metadata.creditsUsed, 1);
assert.ok(response.data.metadata.scrapeId);
console.log(JSON.stringify({ url, markdown: response.data.markdown, retainedPage: process.argv[2] === 'readback' }));
